INSERT INTO resources (id,title,summary,category,tags,publisher,source_url,type,status,collected_at,reviewed_at,reuse,notes,featured) VALUES
('nist-cybersecurity-framework','NIST Cybersecurity Framework','The official CSF 2.0 reference for understanding, communicating and managing organizational cybersecurity risk, with quick-start guides, profiles and translations.','Cybersecurity',ARRAY['NIST','risk management','CSF 2.0','governance']::text[],'National Institute of Standards and Technology','https://www.nist.gov/cyberframework','Standard','Source reviewed','2026-10-02','2026-10-02','Original editorial summary with attribution. Check the source''s terms and third-party image notices before copying materials.','Reviewed the official framework landing page. Inclusion does not establish Mesisem compliance or certification.',TRUE),
('google-helpful-content','Creating helpful, reliable, people-first content','Google Search Central explains how to assess content quality, demonstrate expertise, provide a good page experience and prioritize readers rather than ranking manipulation.','Marketing',ARRAY['SEO','content strategy','search','quality']::text[],'Google Search Central','https://developers.google.com/search/docs/fundamentals/creating-helpful-content','Guide','Source reviewed','2026-10-02','2026-10-02','Original editorial summary. Consult Google''s documentation license and attribution requirements for reuse of source text or code.','Reviewed the primary documentation. No search ranking, indexing or traffic outcome is guaranteed.',TRUE),
('wcag-accessibility','Web Content Accessibility Guidelines (WCAG)','W3C''s introduction to WCAG versions, conformance levels and supporting materials for making web content perceivable, operable, understandable and robust.','Technology',ARRAY['accessibility','WCAG','web standards','inclusive design']::text[],'W3C Web Accessibility Initiative','https://www.w3.org/WAI/standards-guidelines/wcag/','Standard','Source reviewed','2026-10-02','2026-10-02','Original editorial summary. W3C document licensing and notices apply to the underlying standards and supporting documents.','Reviewed the overview, not a conformance audit of this hub or any Mesisem product.',TRUE),
('owasp-top-ten','OWASP Top 10 web application security risks','A developer awareness resource covering major web application security risks. The official project page links to the released 2025 edition and earlier editions.','Cybersecurity',ARRAY['OWASP','application security','secure development']::text[],'OWASP Foundation','https://owasp.org/www-project-top-ten/','Guide','Source reviewed','2026-10-02','2026-10-02','Original editorial summary. Check the license for the specific OWASP document; trademarks and third-party assets have separate notices.','Reviewed the official project page. An awareness list is not a complete security assessment.',FALSE),
('mdn-web-platform','MDN web platform documentation','A starting point for web platform references and guides covering HTML, CSS, JavaScript, HTTP, accessibility, media, browser APIs and developer tools.','Technology',ARRAY['web development','HTML','CSS','JavaScript','HTTP']::text[],'MDN contributors','https://developer.mozilla.org/en-US/docs/Web','Guide','Source reviewed','2026-10-02','2026-10-02','Original editorial summary. MDN text and code have different licensing requirements; consult MDN''s current licensing documentation.','Reviewed the documentation index. Individual linked specifications and APIs have their own status and compatibility information.',FALSE),
('data-gov-catalog','Data.gov open data discovery','The U.S. government open data portal links to datasets, tools and resources for research, application development and visualization, with publisher and metadata information.','Analytics',ARRAY['open data','datasets','research','public information']::text[],'U.S. General Services Administration','https://data.gov/','Dataset','Source reviewed','2026-10-02','2026-10-02','Catalog discovery link, not a mirrored dataset. Check each dataset''s license, restrictions, freshness and privacy implications before use.','Reviewed the portal. Mesisem does not host, validate or claim ownership of the datasets listed there.',TRUE),
('sba-market-research','Market research and competitive analysis','SBA guidance on identifying customers, understanding demand and market conditions, and combining research with competitive analysis when planning a small business.','Consulting',ARRAY['market research','business planning','competitive analysis','startups']::text[],'U.S. Small Business Administration','https://www.sba.gov/business-guide/plan-your-business/market-research-competitive-analysis','Guide','Source reviewed','2026-10-02','2026-10-02','Original editorial summary. Review source and linked third-party rights before reproduction.','The legacy source URL currently resolves to SBA''s consolidated business-planning content. Guidance is U.S.-focused, not country-specific legal advice.',FALSE),
('creative-commons-licenses','Creative Commons licenses and legal tools','The official license directory helps distinguish different permission conditions, including attribution, share-alike, noncommercial use and restrictions on adaptations.','Media',ARRAY['licensing','copyright','attribution','content reuse']::text[],'Creative Commons','https://creativecommons.org/licenses/','Guide','Source reviewed','2026-10-02','2026-10-02','Original editorial summary linking to legal tools. A license applies only when the rights holder actually grants it for the material.','Reviewed the official directory. Public accessibility alone does not imply a Creative Commons license.',FALSE),
('mesisem-public-website-source','Mesisem Global public website source','The public website design repository documents Mesisem''s enterprise positioning and seven service verticals: consulting, technology, cybersecurity, analytics, marketing, media and ventures.','Company',ARRAY['Mesisem','company reference','public source','services']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/tree/73f266536f92d01c9878020104ca8c08a5d90daa','Repository','Company-provided','2026-10-02','2026-10-02','Original summary with links to public source. Repository visibility does not grant a blanket copyright license; branding is retained for company identification.','Reviewed the public repository at a fixed commit. Company descriptions are self-reported, not independent verification of registration, operations, certifications or delivery.',TRUE),
('mesisem-consulting','Mesisem consulting service reference','Mesisem''s published website source describes consulting focused on business strategy, market research, operations and management.','Consulting',ARRAY['Mesisem','strategy','operations','company services']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/blob/73f266536f92d01c9878020104ca8c08a5d90daa/src/components/sections/ServicesGrid.tsx','Repository','Company-provided','2026-10-02','2026-10-02','Original summary of company-provided public source; no blanket source-content license asserted.','Service listing in a public source file. Availability, outcomes and contractual terms have not been independently established.',FALSE),
('mesisem-technology','Mesisem technology service reference','The company service listing describes SaaS platforms, automation systems and API architectures.','Technology',ARRAY['Mesisem','SaaS','automation','APIs']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/blob/73f266536f92d01c9878020104ca8c08a5d90daa/src/components/sections/ServicesGrid.tsx','Repository','Company-provided','2026-10-02','2026-10-02','Original summary of company-provided public source; no blanket source-content license asserted.','A self-reported service description, not an audit of a working platform or a deployment.',FALSE),
('mesisem-cybersecurity','Mesisem cybersecurity service reference','The company service listing describes risk management, compliance support and data security frameworks.','Cybersecurity',ARRAY['Mesisem','security','risk','compliance']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/blob/73f266536f92d01c9878020104ca8c08a5d90daa/src/components/sections/ServicesGrid.tsx','Repository','Company-provided','2026-10-02','2026-10-02','Original summary of company-provided public source; no blanket source-content license asserted.','Does not demonstrate compliance, certification, penetration testing results or security assurance.',FALSE),
('mesisem-analytics','Mesisem analytics service reference','The company service listing describes dashboards, business intelligence and automated reporting.','Analytics',ARRAY['Mesisem','dashboards','business intelligence','reporting']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/blob/73f266536f92d01c9878020104ca8c08a5d90daa/src/components/sections/ServicesGrid.tsx','Repository','Company-provided','2026-10-02','2026-10-02','Original summary of company-provided public source; no blanket source-content license asserted.','Self-reported scope. No client dashboards, private business records or internal metrics are reproduced.',FALSE),
('mesisem-marketing','Mesisem marketing service reference','The company service listing describes branding, campaigns and social media strategy.','Marketing',ARRAY['Mesisem','branding','campaigns','social media']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/blob/73f266536f92d01c9878020104ca8c08a5d90daa/src/components/sections/ServicesGrid.tsx','Repository','Company-provided','2026-10-02','2026-10-02','Original summary of company-provided public source; no blanket source-content license asserted.','No campaign performance, ranking guarantees or client endorsements are inferred from this listing.',FALSE),
('mesisem-media','Mesisem media service reference','The company service listing describes music, film, content production and artist management.','Media',ARRAY['Mesisem','music','film','content production']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/blob/73f266536f92d01c9878020104ca8c08a5d90daa/src/components/sections/ServicesGrid.tsx','Repository','Company-provided','2026-10-02','2026-10-02','Original summary of company-provided public source; no media works, artist data or blanket rights reproduced.','Company-provided service scope, not an independently verified production portfolio.',FALSE),
('mesisem-ventures','Mesisem ventures service reference','The company service listing describes incubation, equity development and startup scaling.','Ventures',ARRAY['Mesisem','incubation','startups','venture development']::text[],'Mesisem Global LLC / mgtechgroup','https://github.com/mgtechgroup/mesisem-global-llc-design/blob/73f266536f92d01c9878020104ca8c08a5d90daa/src/components/sections/ServicesGrid.tsx','Repository','Company-provided','2026-10-02','2026-10-02','Original summary of company-provided public source; no blanket source-content license asserted.','Not a financing offer, investment recommendation or verification of equity agreements.',FALSE),
('mesisem-official-site','Mesisem Global website availability','The company website address is retained for reference. The homepage, about page and services page reported a temporarily paused deployment during collection.','Company',ARRAY['Mesisem','official website','availability']::text[],'Mesisem Global LLC','https://www.mesisemglobal.com/','Guide','Unavailable','2026-10-02','2026-10-02','Availability observation only; no unavailable page content has been reconstructed or copied.','Point-in-time observation, not continuous monitoring. Public repository records remain separately available.',FALSE)
